from pathlib import Path
import gzip,json,hashlib,time
import numpy as np,pandas as pd,scanpy as sc,anndata as ad
from scipy.io import mmread
from scipy import sparse
from threadpoolctl import threadpool_limits
import harmonypy
R=Path(__file__).resolve().parent;src=R/'source_inputs';matrix=R/'GSE202642_matrix.mtx.gz' if (R/'GSE202642_matrix.mtx.gz').exists() else Path('/workspace/scratch/GSE202642_PGAM5_immune_program_associations/GSE202642_matrix.mtx.gz');sc.settings.n_jobs=4
print('Reading full raw matrix',flush=True)
