with threadpool_limits(limits=4):
 with gzip.open(matrix,'rb') as f:x=mmread(f).tocsr().T.tocsr().astype(np.int32)
x=x[sel.to_numpy()].copy();o=meta.loc[sel].copy();o['patient_id']=o.sample_name.astype(str);o.index.name='cell_id';unique=pd.Index(pd.unique(g.gene));mer=sparse.csr_matrix((np.ones(len(g),dtype=np.int32),(np.arange(len(g)),unique.get_indexer(g.gene))),shape=(len(g),len(unique)));x=(x@mer).tocsr();assert np.array_equal(np.asarray(x.sum(1)).ravel(),o.total_counts);assert len(o)==56719
