with threadpool_limits(limits=4):h=harmonypy.run_harmony(a.obsm['X_pca'][:,:40],a.obs,'sample_name',random_state=202642,max_iter_harmony=20,verbose=True)
hz=np.asarray(h.Z_corr);a.obsm['X_pca_harmony']=hz.T if hz.shape[0]==40 else hz;assert a.obsm['X_pca_harmony'].shape==(len(a),40)
