extra=['PGAM5','MYO19','FOXP3','IL2RA','CTLA4','CD4','CD8A','CD8B','IL7R','TCF7','GZMK','LST1','TYROBP','SPP1','TREM2','CD163','CD5L','MARCO','LYZ','HLA-DRA','HBB','HBA1'];genes=list(dict.fromkeys(sum(panels.values(),[])+extra));genes=[g for g in genes if g in a.var_names];vals=a[:,genes].X.toarray();raw=a[:,genes].layers['counts'].toarray();rows=[];profiles=[]
