 ix=a.obs.cluster.eq(c).to_numpy();n=ix.sum();row={'cluster':c,'cells':int(n),'patients':int(a.obs.loc[ix,'patient_id'].nunique()),'largest_patient_fraction':float(a.obs.loc[ix,'patient_id'].value_counts(normalize=True).max()),'median_total_counts':float(a.obs.loc[ix,'total_counts'].median()),'median_pct_mt':float(a.obs.loc[ix,'pct_mt'].median())}
