 profiles.append(row)
 for i,gene in enumerate(genes):rows.append({'cluster':c,'gene':gene,'cells':int(n),'fraction':float((raw[ix,i]>0).mean()),'mean_log1p_CP10k':float(vals[ix,i].mean())})
